std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return (char)tolower(c);});return s;}
std::string hex(const std::vector<unsigned char>& bytes){const char* h="0123456789abcdef";std::string s;for(auto c:bytes){s+=h[c>>4];s+=h[c&15];}return s;}
std::string tokenFor(const std::string& origin){BCRYPT_ALG_HANDLE alg=nullptr;BCRYPT_HASH_HANDLE hash=nullptr;DWORD size=0,got=0;std::vector<unsigned char> result(32);require(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,BCRYPT_ALG_HANDLE_HMAC_FLAG)==0,"Cannot initialize pairing security");BCryptGetProperty(alg,BCRYPT_OBJECT_LENGTH,(PUCHAR)&size,sizeof(size),&got,0);std::vector<unsigned char> object(size);auto rc=BCryptCreateHash(alg,&hash,object.data(),size,(PUCHAR)secret.data(),(ULONG)secret.size(),0);std::string value="origin:"+origin;if(rc==0)rc=BCryptHashData(hash,(PUCHAR)value.data(),(ULONG)value.size(),0);if(rc==0)rc=BCryptFinishHash(hash,result.data(),32,0);if(hash)BCryptDestroyHash(hash);BCryptCloseAlgorithmProvider(alg,0);require(rc==0,"Cannot generate pairing token");return hex(result);}
bool equalToken(const std::string&a,const std::string&b){if(a.size()!=b.size())return false;unsigned char diff=0;for(size_t i=0;i<a.size();i++)diff|=a[i]^b[i];return diff==0;}
